// מציגים במאגר הציבורי רק פריטים שיש להם תוכן אמיתי או תת־קטגוריות שימושיות.
// כך לא נוצרים כרטיסים ריקים שמובילים למסכי placeholder.
function pruneArchive(parent, seen=new Set()){
  if(seen.has(parent)) return [];
  seen.add(parent);
  const items=archiveTree[parent]||[];
  return items.filter(item=>{
    const children=archiveTree[item.id];
    if(children){
      const kept=pruneArchive(item.id,new Set(seen));
      archiveTree[item.id]=kept;
      return kept.length>0 || Boolean(archiveContent[item.id]);
    }
    return Boolean(archiveContent[item.id]);
  });
}
archiveTree.root=pruneArchive('root');

let archivePath=['root'];

function escArchive(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}

function renderArchive(){
  const current=archivePath[archivePath.length-1];
  const q=($('#archiveSearch')?.value||'').trim().toLowerCase();
  const raw=archiveTree[current]||[];
  const items=raw.filter(x=>!q || x.name.toLowerCase().includes(q) || (archiveContent[x.id]||'').toLowerCase().includes(q));
  $('#archiveBreadcrumbs').innerHTML=archivePath.map((id,i)=>`<button data-level="${i}">${escArchive(archiveLabels[id]||id)}</button>`).join('');
  $('#archiveBack').style.visibility=archivePath.length>1?'visible':'hidden';
  $('#archiveGrid').innerHTML=items.map((x,i)=>`<article class="archive-card" data-i="${i}"><div class="archive-icon" data-mark="${escArchive(x.name[0]||'•')}"></div><h3>${escArchive(x.name)}</h3><p>${archiveTree[x.id]?'תיקייה עם תוכן פנימי':'תוכן מתוך המאגר'}</p><span class="archive-meta">${archiveTree[x.id]?'פתח קטגוריה':'פתח תוכן'}</span><span class="archive-arrow">←</span></article>`).join('');
  $$('#archiveGrid .archive-card').forEach((el)=>el.onclick=()=>{
     const x=items[+el.dataset.i];
     if(archiveTree[x.id]){archivePath.push(x.id);$('#archiveSearch').value='';$('#archiveViewer').hidden=true;renderArchive();}
     else{openArchiveContent(x.id,x.name);}
  });
  $$('#archiveBreadcrumbs button').forEach(b=>b.onclick=()=>{archivePath=archivePath.slice(0,+b.dataset.level+1);$('#archiveSearch').value='';$('#archiveViewer').hidden=true;renderArchive();});
}

function openArchiveContent(id,name){
  let txt=archiveContent[id]; if(!txt)return;
  let media=id==='facility-extra'?'<img src="assets/facility-extra.jpg" alt="מתקן מתוך המאגר">':'';
  $('#archiveViewer').innerHTML=`<div class="viewer-tag">NA-C ARCHIVE</div><h3>${escArchive(name)}</h3><pre>${escArchive(txt)}</pre>${media}`;
  $('#archiveViewer').hidden=false;
  $('#archiveViewer').scrollIntoView({behavior:'smooth',block:'start'});
}

