function pick(arr){return arr[Math.floor(Math.random()*arr.length)]}function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
let currentGame='mix', difficulty='medium', score=0, streak=0, round=1, speedTimer=null, locked=false, correctCount=0, answeredCount=0;
let usedQuestionKeys=new Set();
const GAME_LENGTH=10;
