function qkey(type,g,extra=''){return `${type}-${g?.year||''}-${extra}`}
function different(factory){let q;for(let i=0;i<250;i++){q=factory();if(!usedQuestionKeys.has(q.key)){usedQuestionKeys.add(q.key);return q}}// Pool exhausted: never repeat inside a run; start a fresh deck only after all available questions were seen.
usedQuestionKeys.clear();q=factory();usedQuestionKeys.add(q.key);return q}
function makeAnimal(){return different(()=>{const g=pick(animalPool),reverse=Math.random()>.5;if(reverse){let opts=shuffle([g.name,...shuffle(animalPool.filter(x=>x.year!==g.year)).slice(0,3).map(x=>x.name)]);return{key:qkey('ar',g),title:`איזו שכבה מזוהה עם ${g.animal}?`,meta:`חיית שכבה · ${g.year}`,opts,ans:g.name}}let opts=shuffle([g.animal,...shuffle(animalPool.filter(x=>x.year!==g.year)).slice(0,3).map(x=>x.animal)]);return{key:qkey('a',g),title:`מה החיה של שכבת ${g.name}?`,meta:`שנת סיום ${g.year}`,opts,ans:g.animal}})}
function makeYear(){return different(()=>{const g=pick(generations),reverse=Math.random()>.5;if(reverse){let near=generations.filter(x=>Math.abs(x.year-g.year)<8&&x.year!==g.year);let opts=shuffle([g.name,...shuffle(near.length>=3?near:generations.filter(x=>x.year!==g.year)).slice(0,3).map(x=>x.name)]);return{key:qkey('yr',g),title:`איזו שכבה סיימה בשנת ${g.year}?`,meta:'מכירים את ציר הזמן?',opts,ans:g.name}}let years=shuffle(generations.filter(x=>x.year!==g.year)).slice(0,3).map(x=>x.year);return{key:qkey('y',g),title:`מתי שכבת ${g.name} סיימה?`,meta:g.animal==='—'?'ציר הזמן':`רמז: ${g.animal}`,opts:shuffle([g.year,...years]),ans:g.year}})}
function makeFact(){return different(()=>{const real=Math.random()>.5,fact=pick(real?trueFacts:falseFacts);return{key:'f-'+fact,title:`“${fact}”`,meta:'אמת או חרטא?',opts:['אמת','חרטא'],ans:real?'אמת':'חרטא'}})}
function makeOdd(){return different(()=>{const base=pick(animalPool);let sameDecade=animalPool.filter(x=>Math.floor(x.year/10)===Math.floor(base.year/10)&&x.year!==base.year);if(sameDecade.length<2)sameDecade=animalPool.filter(x=>x.year!==base.year);const trio=shuffle(sameDecade).slice(0,2);const odd=pick(animalPool.filter(x=>Math.abs(x.year-base.year)>10));const opts=shuffle([base.name,...trio.map(x=>x.name),odd.name]);return{key:qkey('odd',base,odd.year),title:'מי לא שייך לאותה תקופה?',meta:`שלוש שכבות מאותו עשור — אחת לא`,opts,ans:odd.name}})}
