const facilityEntries=Object.entries(facilityHistory).flatMap(([year,names])=>names.map(name=>({year:+year,name})));
function facilityQuestion(){return different(()=>{const f=pick(facilityEntries);const wrong=shuffle([...new Set(facilityEntries.filter(x=>x.year!==f.year).map(x=>x.year))]).slice(0,3);return{key:'facility-'+f.year+'-'+f.name,title:`באיזו שנה הופיע המתקן “${f.name}”?`,meta:'🏗️ ארכיון המתקנים',opts:shuffle([f.year,...wrong]),ans:f.year}})}
function facilityNameQuestion(){return different(()=>{const year=+pick(Object.keys(facilityHistory));const ans=pick(facilityHistory[year]);const wrong=shuffle(facilityEntries.filter(x=>x.year!==year).map(x=>x.name)).slice(0,3);return{key:'facilityname-'+year+'-'+ans,title:`איזה מהמתקנים הבאים מופיע בשנת ${year}?`,meta:'🚧 מזהים לפי שנה',opts:shuffle([ans,...wrong]),ans}})}
