function renderFacilityTyped(){const q=facilityTypedQuestion();locked=false;$('#gameBox').innerHTML=`<div class="typed-game facility-typed"><div class=game-meta>✍️ מי זוכר מתקן? · ${difficultyConfig[difficulty].label}</div><h3>${q.title}</h3><form id="typedForm" class="typed-form"><input id="typedAnswer" autocomplete="off" placeholder="שם המתקן..."><button type="submit">בדיקה</button></form><div class="mini-note">כל אחד מהמתקנים של אותה שנה מתקבל כתשובה נכונה.</div><div class="game-feedback" id="feedback"></div><button class="next-btn" id="typedNext">הבא ↻</button></div>`;const input=$('#typedAnswer');input.focus();$('#typedForm').onsubmit=e=>{e.preventDefault();if(locked)return;const val=normalizeTyped(input.value);if(!val)return;locked=true;const ok=q.answers.map(normalizeTyped).includes(val);answeredCount++;input.disabled=true;$('#typedForm button').disabled=true;if(ok){correctCount++;streak++;score+=Math.round(20*difficultyConfig[difficulty].mult);$('#feedback').textContent='🔥 פגיעה ישירה. מתקן נכון!';$('#feedback').className='game-feedback good'}else{streak=0;$('#feedback').innerHTML=`לא הפעם. לדוגמה: <b>${q.answers.slice(0,3).join(' · ')}</b>`;$('#feedback').className='game-feedback bad'}round++;hud();if(answeredCount>=GAME_LENGTH)setTimeout(finishGame,900);else{$('#typedNext').classList.add('ready');$('#typedNext').onclick=newGame}}}
function renderFacilityChain(){locked=false;let years;for(let i=0;i<100;i++){years=shuffle(Object.keys(facilityHistory).map(Number)).slice(0,difficulty==='easy'?3:difficulty==='hard'?5:4).sort((a,b)=>a-b);const key='facilitychain-'+years.join('-');if(!usedQuestionKeys.has(key)){usedQuestionKeys.add(key);break}}const cards=shuffle(years.map(y=>({year:y,name:pick(facilityHistory[y])})));$('#gameBox').innerHTML=`<div><div class=game-meta>🔗 שרשרת מתקנים · מהישן לחדש</div><h3>סדרו את המתקנים לפי השנים</h3><div class=order-list>${cards.map(c=>`<button class="order-item facility-order" data-year="${c.year}"><span>${c.name}</span><b>?</b></button>`).join('')}</div><div class="game-feedback" id="feedback"></div></div>`;let chosen=[];$$('.facility-order').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('selected');chosen.push(+b.dataset.year);b.querySelector('b').textContent=chosen.length;if(chosen.length===cards.length){const ok=chosen.every((v,i,a)=>i===0||a[i-1]<v);answeredCount++;if(ok){correctCount++;streak++;score+=Math.round(30*difficultyConfig[difficulty].mult);$('#feedback').textContent='🔥 שרשרת מושלמת!';$('#feedback').className='game-feedback good'}else{streak=0;$('#feedback').textContent='כמעט — הסדר לא כרונולוגי.';$('#feedback').className='game-feedback bad'}round++;hud();setTimeout(()=>answeredCount>=GAME_LENGTH?finishGame():newGame(),1000)}})}
function renderFacilityArchive(){const host=$('#facilityYears');if(!host)return;const total=facilityEntries.length;$('#facilityStats').innerHTML=`<div><b>${Object.keys(facilityHistory).length}</b><span>שנים</span></div><div><b>${total}</b><span>מתקנים מתועדים</span></div><div><b>2003—2026</b><span>טווח הארכיון</span></div>`;host.innerHTML=Object.entries(facilityHistory).sort((a,b)=>b[0]-a[0]).map(([year,names])=>`<details class="facility-year"><summary><span>${year}</span><b>${names.length} מתקנים</b><i>+</i></summary><div class="facility-chips">${names.map(n=>`<span>${n}</span>`).join('')}</div></details>`).join('')}

function gradeLabel(n){return n>=90?'אגדה של הנשיא':n>=80?'מטורף':n>=70?'חזק מאוד':n>=60?'יפה מאוד':'יש עוד מה לחרוש'}
function finishGame(){clearInterval(speedTimer);locked=true;const grade=Math.round((correctCount/GAME_LENGTH)*100);$('#gameBox').innerHTML=`<div class=game-finish><span class=eyebrow>GAME COMPLETE</span><h3>סיימת את המשחק</h3><div class=final-grade>${grade}</div><div class=final-grade-label>${gradeLabel(grade)}</div><p>ענית נכון על <b>${correctCount}</b> מתוך <b>${GAME_LENGTH}</b> שאלות · ניקוד משחק: <b>${score}</b></p><button class=restart-btn>משחק חדש ↻</button></div>`;$('.restart-btn').onclick=()=>{score=0;streak=0;round=1;correctCount=0;answeredCount=0;usedQuestionKeys.clear();hud();newGame()}}
function adaptQuestion(q){const qq={...q,opts:[...q.opts]};if(difficulty==='easy'&&qq.opts.length>3){const wrong=shuffle(qq.opts.filter(x=>String(x)!==String(qq.ans))).slice(0,2);qq.opts=shuffle([qq.ans,...wrong])}if(difficulty==='hard')qq.meta='🔥 רמת אגדה · '+qq.meta;return qq}
function renderQuestion(q,speed=false){q=adaptQuestion(q);locked=false;const box=$('#gameBox');const speedHtml=speed?`<div class="speed-clock" id="speedClock">${difficultyConfig[difficulty].time} שניות</div><div class="game-progress"><i id="gameProgress"></i></div>`:'';box.innerHTML=`<div>${speedHtml}<div class=game-meta>${q.meta}</div><h3>${q.title}</h3><div class=choices>${q.opts.map(o=>`<button class=choice data-answer="${String(o)}" data-correct="${String(q.ans)}">${o}</button>`).join('')}</div><div class="game-feedback" id="feedback"></div><button class=next-btn>הבא ↻</button></div>`;bindChoices(speed);if(speed)startClock()}
function answer(btn,timedOut=false){if(locked)return;locked=true;clearInterval(speedTimer);const correct=!timedOut&&btn&&btn.dataset.answer===btn.dataset.correct;$$('.choice').forEach(x=>x.disabled=true);if(btn)btn.classList.add(correct?'good':'bad');$$('.choice').find(x=>x.dataset.answer===x.dataset.correct)?.classList.add('good');answeredCount++;if(correct){correctCount++;streak++;score+=Math.round((10+Math.min(streak*2,20))*difficultyConfig[difficulty].mult);$('#feedback').textContent=streak>=3?`🔥 נכון! רצף של ${streak}`:'✓ נכון!';$('#feedback').className='game-feedback good'}else{streak=0;$('#feedback').textContent=timedOut?'⏱ הזמן נגמר!':'לא הפעם — התשובה הנכונה מסומנת בירוק';$('#feedback').className='game-feedback bad'}round++;hud();setTimeout(()=>{if(answeredCount>=GAME_LENGTH){finishGame();return}if(currentGame==='speed'||currentGame==='mix')newGame();else $('.next-btn')?.classList.add('ready')},correct?650:950)}
function bindChoices(speed){$$('.choice').forEach(b=>b.onclick=()=>answer(b));const n=$('.next-btn');if(n)n.onclick=newGame}
function startClock(){let t=difficultyConfig[difficulty].time;const bar=$('#gameProgress'),clock=$('#speedClock');speedTimer=setInterval(()=>{t-=.1;if(bar)bar.style.width=`${Math.max(0,t/difficultyConfig[difficulty].time*100)}%`;if(clock)clock.textContent=`${Math.ceil(t)} שניות`;if(t<=0){clearInterval(speedTimer);answer(null,true)}},100)}
function makeTimeline(){const timelineCount=difficulty==='easy'?3:difficulty==='hard'?5:4;let picks;for(let i=0;i<100;i++){picks=shuffle(history).slice(0,timelineCount).sort((a,b)=>Math.random()-.5);const key='timeline-'+picks.map(x=>x[0]).sort().join('-');if(!usedQuestionKeys.has(key)){usedQuestionKeys.add(key);break}}locked=false;$('#gameBox').innerHTML=`<div><div class=game-meta>לחצו לפי הסדר — מהישן לחדש</div><h3>סדרו את ההיסטוריה</h3><div class=order-list>${picks.map((h,i)=>`<button class=order-item data-year="${h[0]}"><span>${h[1]}</span><b>?</b></button>`).join('')}</div><div class=game-feedback id=feedback></div><div class=mini-note>כל לחיצה מקבעת שלב בציר הזמן.</div></div>`;let chosen=[];$$('.order-item').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('selected');chosen.push(+b.dataset.year);b.querySelector('b').textContent=chosen.length;if(chosen.length===picks.length){locked=true;const ok=chosen.every((v,i,a)=>i===0||a[i-1]<=v);answeredCount++;if(ok){correctCount++;score+=25;streak++;$('#feedback').textContent='🔥 בול. ציר הזמן מושלם';$('#feedback').className='game-feedback good'}else{streak=0;$('#feedback').textContent='לא בדיוק — נסו שוב עם סדר השנים';$('#feedback').className='game-feedback bad'}round++;hud();setTimeout(()=>answeredCount>=GAME_LENGTH?finishGame():newGame(),1100)}})}
function renderTyped(){const q=makeTyped();locked=false;const hint=difficulty==='easy'?'אפשר לענות במילה או במספר — לא צריך ניסוח מלא.':difficulty==='hard'?'בלי אפשרויות ובלי רמזים. רק מהראש.':'הקלידו את התשובה ולחצו Enter.';$('#gameBox').innerHTML=`<div class="typed-game"><div class=game-meta>⌨️ תשובה חופשית · ${difficultyConfig[difficulty].label}</div><h3>${q.title}</h3><form id="typedForm" class="typed-form"><input id="typedAnswer" autocomplete="off" autocapitalize="off" placeholder="התשובה שלך..." aria-label="הקלדת תשובה"><button type="submit">בדיקה</button></form><div class="mini-note">${hint}</div><div class="game-feedback" id="feedback"></div><button class="next-btn" id="typedNext">הבא ↻</button></div>`;const input=$('#typedAnswer');input.focus();$('#typedForm').onsubmit=e=>{e.preventDefault();if(locked)return;const val=normalizeTyped(input.value);if(!val)return;locked=true;const accepted=q.answers.map(normalizeTyped);const correct=accepted.includes(val);answeredCount++;input.disabled=true;$('#typedForm button').disabled=true;if(correct){correctCount++;streak++;score+=Math.round((15+Math.min(streak*3,24))*difficultyConfig[difficulty].mult);$('#feedback').textContent=streak>=3?`🔥 מדויק. רצף של ${streak}`:'✓ תשובה נכונה';$('#feedback').className='game-feedback good'}else{streak=0;$('#feedback').innerHTML=`לא הפעם — התשובה: <b>${q.answers[0]}</b>`;$('#feedback').className='game-feedback bad'}round++;hud();if(answeredCount>=GAME_LENGTH){setTimeout(finishGame,900)}else{$('#typedNext').classList.add('ready');$('#typedNext').onclick=newGame}}}
function newGame(){clearInterval(speedTimer);hud();if(currentGame==='timeline'){makeTimeline();return}if(currentGame==='type'){renderTyped();return}if(currentGame==='facilitytype'){renderFacilityTyped();return}if(currentGame==='facilitychain'){renderFacilityChain();return}let q;if(currentGame==='animal')q=makeAnimal();else if(currentGame==='year')q=makeYear();else if(currentGame==='fact')q=makeFact();else if(currentGame==='hall')q=makeHall();else if(currentGame==='odd')q=makeOdd();else if(currentGame==='facility')q=facilityQuestion();else if(currentGame==='facilityrush')q=pick([facilityQuestion,facilityNameQuestion])();else if(currentGame==='speed')q=pick([makeAnimal,makeYear,makeFact,makeOdd,makeHall,facilityQuestion])();else q=pick([makeAnimal,makeYear,makeFact,makeOdd,makeHall,facilityQuestion,facilityNameQuestion])();renderQuestion(q,currentGame==='speed'||currentGame==='facilityrush')}
$$('.game-tabs button').forEach(b=>b.onclick=()=>{$$('.game-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentGame=b.dataset.game;score=0;streak=0;round=1;correctCount=0;answeredCount=0;usedQuestionKeys.clear();newGame()});
$$('.difficulty-tabs button').forEach(b=>b.onclick=()=>{$$('.difficulty-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');difficulty=b.dataset.level;usedQuestionKeys.clear();const hints={easy:'3 תשובות · 14 שניות בספיד · ניקוד ×0.8',medium:'4 תשובות · 10 שניות בספיד · ניקוד רגיל',hard:'4 תשובות · 6 שניות בספיד · ציר זמן ארוך · ניקוד ×1.6'};$('#difficultyHint').textContent=hints[difficulty];score=0;streak=0;round=1;correctCount=0;answeredCount=0;hud();newGame()});

$('#archiveSearch').oninput=renderArchive;
$('#archiveBack').onclick=()=>{if(archivePath.length>1){archivePath.pop();$('#archiveSearch').value='';$('#archiveViewer').hidden=true;renderArchive();}};

